#include "categories.hpp"

const std::vector<Category>& Categories() {
    static const std::vector<Category> categories = {
        {L"", L"System Summary", {
            {L"Operating System", L"SELECT Caption,Version,BuildNumber,OSArchitecture,Manufacturer,WindowsDirectory,SystemDirectory,Locale,BootDevice,TotalVisibleMemorySize,FreePhysicalMemory,TotalVirtualMemorySize,FreeVirtualMemory,SizeStoredInPagingFiles,FreeSpaceInPagingFiles FROM Win32_OperatingSystem",
                {L"Caption",L"Version",L"BuildNumber",L"OSArchitecture",L"Manufacturer",L"WindowsDirectory",L"SystemDirectory",L"Locale",L"BootDevice",L"TotalVisibleMemorySize",L"FreePhysicalMemory",L"TotalVirtualMemorySize",L"FreeVirtualMemory",L"SizeStoredInPagingFiles",L"FreeSpaceInPagingFiles"}},
            {L"Computer System", L"SELECT Name,Manufacturer,Model,SystemType,SystemSKUNumber,TotalPhysicalMemory,Domain,UserName,HypervisorPresent,PCSystemType FROM Win32_ComputerSystem",
                {L"Name",L"Manufacturer",L"Model",L"SystemType",L"SystemSKUNumber",L"TotalPhysicalMemory",L"Domain",L"UserName",L"HypervisorPresent",L"PCSystemType"}},
            {L"Processor", L"SELECT Name,Manufacturer,MaxClockSpeed,NumberOfCores,NumberOfLogicalProcessors,ProcessorId FROM Win32_Processor",
                {L"Name",L"Manufacturer",L"MaxClockSpeed",L"NumberOfCores",L"NumberOfLogicalProcessors",L"ProcessorId"}},
            {L"BIOS", L"SELECT Manufacturer,SMBIOSBIOSVersion,SMBIOSMajorVersion,SMBIOSMinorVersion,EmbeddedControllerMajorVersion,EmbeddedControllerMinorVersion,ReleaseDate,SerialNumber FROM Win32_BIOS",
                {L"Manufacturer",L"SMBIOSBIOSVersion",L"SMBIOSMajorVersion",L"SMBIOSMinorVersion",L"EmbeddedControllerMajorVersion",L"EmbeddedControllerMinorVersion",L"ReleaseDate",L"SerialNumber"}},
            {L"BaseBoard", L"SELECT Manufacturer,Product,Version,SerialNumber FROM Win32_BaseBoard",
                {L"Manufacturer",L"Product",L"Version",L"SerialNumber"}},
            {L"Time Zone", L"SELECT Caption,StandardName FROM Win32_TimeZone", {L"Caption",L"StandardName"}},
            {L"Page File", L"SELECT Caption,AllocatedBaseSize,CurrentUsage FROM Win32_PageFileUsage", {L"Caption",L"AllocatedBaseSize",L"CurrentUsage"}},
        }},

        {L"", L"Hardware Resources", {}},
        {L"Hardware Resources", L"Conflicts/Sharing", {{L"Conflicts/Sharing", L"SELECT Antecedent,Dependent FROM Win32_PnPAllocatedResource", {L"Antecedent",L"Dependent"}}}},
        {L"Hardware Resources", L"DMA", {{L"DMA", L"SELECT Name,DMAChannel,Status FROM Win32_DMAChannel", {L"Name",L"DMAChannel",L"Status"}}}},
        {L"Hardware Resources", L"Forced Hardware", {{L"Forced Hardware", L"SELECT Name,PNPDeviceID,ConfigManagerErrorCode FROM Win32_PnPEntity WHERE ConfigManagerUserConfig=True", {L"Name",L"PNPDeviceID",L"ConfigManagerErrorCode"}}}},
        {L"Hardware Resources", L"I/O", {{L"I/O", L"SELECT Name,StartingAddress,EndingAddress FROM Win32_PortResource", {L"Name",L"StartingAddress",L"EndingAddress"}}}},
        {L"Hardware Resources", L"IRQs", {{L"IRQs", L"SELECT Name,IRQNumber,Status FROM Win32_IRQResource", {L"Name",L"IRQNumber",L"Status"}}}},
        {L"Hardware Resources", L"Memory", {{L"Memory", L"SELECT Name,StartingAddress,EndingAddress FROM Win32_DeviceMemoryAddress", {L"Name",L"StartingAddress",L"EndingAddress"}}}},

        {L"", L"Components", {}},
        {L"Components", L"Multimedia", {}},
        {L"Multimedia", L"Audio Codecs", {{L"Audio Codecs", L"SELECT Name,Description,Manufacturer,Version FROM Win32_CodecFile WHERE Group='Audio'", {L"Name",L"Description",L"Manufacturer",L"Version"}}}},
        {L"Multimedia", L"Video Codecs", {{L"Video Codecs", L"SELECT Name,Description,Manufacturer,Version FROM Win32_CodecFile WHERE Group='Video'", {L"Name",L"Description",L"Manufacturer",L"Version"}}}},
        {L"Multimedia", L"CD-ROM", {{L"CD-ROM", L"SELECT Name,Drive,Manufacturer,MediaLoaded,PNPDeviceID,Status FROM Win32_CDROMDrive", {L"Name",L"Drive",L"Manufacturer",L"MediaLoaded",L"PNPDeviceID",L"Status"}}}},
        {L"Multimedia", L"Sound Device", {{L"Sound Device", L"SELECT Name,Manufacturer,Status,PNPDeviceID FROM Win32_SoundDevice", {L"Name",L"Manufacturer",L"Status",L"PNPDeviceID"}}}},
        {L"Components", L"Display", {{L"Display", L"SELECT Name,AdapterCompatibility,AdapterRAM,DriverVersion,VideoProcessor,CurrentHorizontalResolution,CurrentVerticalResolution,CurrentRefreshRate FROM Win32_VideoController", {L"Name",L"AdapterCompatibility",L"AdapterRAM",L"DriverVersion",L"VideoProcessor",L"CurrentHorizontalResolution",L"CurrentVerticalResolution",L"CurrentRefreshRate"}}}},
        {L"Components", L"Infrared", {{L"Infrared", L"SELECT Name,Description,PNPDeviceID,Status FROM Win32_InfraredDevice", {L"Name",L"Description",L"PNPDeviceID",L"Status"}}}},
        {L"Components", L"Input", {}},
        {L"Input", L"Keyboard", {{L"Keyboard", L"SELECT Name,Description,DeviceID,Status FROM Win32_Keyboard", {L"Name",L"Description",L"DeviceID",L"Status"}}}},
        {L"Input", L"Pointing Device", {{L"Pointing Device", L"SELECT Name,Description,DeviceID,Status FROM Win32_PointingDevice", {L"Name",L"Description",L"DeviceID",L"Status"}}}},
        {L"Components", L"Modem", {{L"Modem", L"SELECT Name,Description,DeviceID,Status FROM Win32_POTSModem", {L"Name",L"Description",L"DeviceID",L"Status"}}}},
        {L"Components", L"Network", {}},
        {L"Network", L"Adapter", {{L"Adapter", L"SELECT Name,Manufacturer,MACAddress,NetConnectionID,Speed,PNPDeviceID FROM Win32_NetworkAdapter", {L"Name",L"Manufacturer",L"MACAddress",L"NetConnectionID",L"Speed",L"PNPDeviceID"}}}},
        {L"Network", L"Protocol", {{L"Protocol", L"SELECT Name,Description,Status FROM Win32_NetworkProtocol", {L"Name",L"Description",L"Status"}}}},
        {L"Network", L"WinSock", {{L"WinSock", L"SELECT Name,Description,Status FROM Win32_NetworkProtocol", {L"Name",L"Description",L"Status"}}}},
        {L"Components", L"Ports", {}},
        {L"Ports", L"Serial", {{L"Serial", L"SELECT Name,Description,DeviceID,PNPDeviceID FROM Win32_SerialPort", {L"Name",L"Description",L"DeviceID",L"PNPDeviceID"}}}},
        {L"Ports", L"Parallel", {{L"Parallel", L"SELECT Name,Description,DeviceID,PNPDeviceID FROM Win32_ParallelPort", {L"Name",L"Description",L"DeviceID",L"PNPDeviceID"}}}},
        {L"Components", L"Storage", {}},
        {L"Storage", L"Drives", {{L"Drives", L"SELECT DeviceID,Description,FileSystem,Size,FreeSpace,VolumeName,VolumeSerialNumber FROM Win32_LogicalDisk", {L"DeviceID",L"Description",L"FileSystem",L"Size",L"FreeSpace",L"VolumeName",L"VolumeSerialNumber"}}}},
        {L"Storage", L"Disks", {{L"Disks", L"SELECT Model,Manufacturer,InterfaceType,Size,SerialNumber,PNPDeviceID FROM Win32_DiskDrive", {L"Model",L"Manufacturer",L"InterfaceType",L"Size",L"SerialNumber",L"PNPDeviceID"}}}},
        {L"Storage", L"SCSI", {{L"SCSI", L"SELECT Name,Manufacturer,DeviceID,PNPDeviceID,Status FROM Win32_SCSIController", {L"Name",L"Manufacturer",L"DeviceID",L"PNPDeviceID",L"Status"}}}},
        {L"Storage", L"IDE", {{L"IDE", L"SELECT Name,Manufacturer,DeviceID,PNPDeviceID,Status FROM Win32_IDEController", {L"Name",L"Manufacturer",L"DeviceID",L"PNPDeviceID",L"Status"}}}},
        {L"Components", L"Printing", {{L"Printing", L"SELECT Name,DriverName,PortName,Default,Network,Status FROM Win32_Printer", {L"Name",L"DriverName",L"PortName",L"Default",L"Network",L"Status"}}}},
        {L"Components", L"Problem Devices", {{L"Problem Devices", L"SELECT Name,PNPDeviceID,ConfigManagerErrorCode,Status FROM Win32_PnPEntity WHERE ConfigManagerErrorCode <> 0", {L"Name",L"PNPDeviceID",L"ConfigManagerErrorCode",L"Status"}}}},
        {L"Components", L"USB", {{L"USB", L"SELECT Name,Manufacturer,PNPDeviceID,Status FROM Win32_USBController", {L"Name",L"Manufacturer",L"PNPDeviceID",L"Status"}}}},

        {L"", L"Software Environment", {}},
        {L"Software Environment", L"System Drivers", {{L"System Drivers", L"SELECT Name,DisplayName,State,StartMode,PathName FROM Win32_SystemDriver", {L"Name",L"DisplayName",L"State",L"StartMode",L"PathName"}}}},
        {L"Software Environment", L"Environment Variables", {{L"Environment Variables", L"SELECT Name,VariableValue,UserName,SystemVariable FROM Win32_Environment", {L"Name",L"VariableValue",L"UserName",L"SystemVariable"}}}},
        {L"Software Environment", L"Print Jobs", {{L"Print Jobs", L"SELECT Name,Document,Owner,Status,TotalPages FROM Win32_PrintJob", {L"Name",L"Document",L"Owner",L"Status",L"TotalPages"}}}},
        {L"Software Environment", L"Network Connections", {{L"Network Connections", L"SELECT Name,LocalName,RemoteName,ConnectionState,UserName FROM Win32_NetworkConnection", {L"Name",L"LocalName",L"RemoteName",L"ConnectionState",L"UserName"}}}},
        {L"Software Environment", L"Running Tasks", {{L"Running Tasks", L"SELECT Name,ProcessId,ExecutablePath,CommandLine FROM Win32_Process", {L"Name",L"ProcessId",L"ExecutablePath",L"CommandLine"}}}},
        {L"Software Environment", L"Loaded Modules", {{L"Loaded Modules", L"SELECT Name,ProcessId,ExecutablePath FROM Win32_Process", {L"Name",L"ProcessId",L"ExecutablePath"}}}},
        {L"Software Environment", L"Services", {{L"Services", L"SELECT Name,DisplayName,State,StartMode,PathName,StartName FROM Win32_Service", {L"Name",L"DisplayName",L"State",L"StartMode",L"PathName",L"StartName"}}}},
        {L"Software Environment", L"Program Groups", {{L"Program Groups", L"SELECT Name,UserName FROM Win32_LogicalProgramGroup", {L"Name",L"UserName"}}}},
        {L"Software Environment", L"Startup Programs", {{L"Startup Programs", L"SELECT Caption,Command,User,Location FROM Win32_StartupCommand", {L"Caption",L"Command",L"User",L"Location"}}}},
        {L"Software Environment", L"OLE Registration", {{L"OLE Registration", L"SELECT Caption,ComponentId,InprocServer32,LocalServer32,ProgId FROM Win32_ClassicCOMClassSetting", {L"Caption",L"ComponentId",L"InprocServer32",L"LocalServer32",L"ProgId"}}}},
        {L"Software Environment", L"Windows Error Reporting", {{L"Windows Error Reporting", L"SELECT TimeGenerated,SourceName,Message FROM Win32_NTLogEvent WHERE Logfile='Application' AND EventIdentifier=1001 AND SourceName='Windows Error Reporting'", {L"TimeGenerated",L"SourceName",L"Message"}}}},
    };
    return categories;
}
